(6248238, 924033, 93565, '<td valign="top">Hey! Somebody else shooting cyclocross! Pretty good sharpness on this pan, but something about this feels very static and I can''t figure out why.</td>', 'Hey! Somebody else shooting cyclocross! Pretty good sharpness on this pan, but something about this feels very static and I can''t figure out why.', '2010-12-08 01:23:38.000000', NULL, 1),
(6248249, 924046, 93565, '<td valign="top">I''m surprised at how orange the trail left behind is, but the vibrant color really helps the photo overall.</td>', 'I''m surprised at how orange the trail left behind is, but the vibrant color really helps the photo overall.', '2010-12-08 01:28:14.000000', NULL, 1),
(6248250, 924227, 51638, '<td valign="top">I''d have gone with a slightly faster shutter speed, so that the horses (if that''s what they are) were still a little more visible.</td>', 'I''d have gone with a slightly faster shutter speed, so that the horses (if that''s what they are) were still a little more visible.', '2010-12-08 01:28:22.000000', NULL, 1),
(6248260, 924283, 93565, '<td valign="top">By far the best of the dog shots. Interesting choice cropping/framing the dog how you did, but I like it. Good shot.</td>', 'By far the best of the dog shots. Interesting choice cropping/framing the dog how you did, but I like it. Good shot.', '2010-12-08 01:30:06.000000', NULL, 1),
(6248261, 923756, 51638, '<td valign="top">Motion blur, or just OOF?</td>', 'Motion blur, or just OOF?', '2010-12-08 01:30:54.000000', NULL, 1),
(6248264, 923726, 93565, '<td valign="top">I like your BW processing here. One of the better "public" type shots in the challenge.</td>', 'I like your BW processing here. One of the better "public" type shots in the challenge.', '2010-12-08 01:31:34.000000', NULL, 1),
(6248266, 924163, 51638, '<td valign="top">Nice work. Well composed and shot.</td>', 'Nice work. Well composed and shot.', '2010-12-08 01:31:54.000000', NULL, 1),
(6248270, 924053, 93565, '<td valign="top">I''ve no clue what I''m looking at, but I love it. This is just so awesome. The striations in the blue contrast really well with the smoothness of the yellow area. Curious to see notes after the fact to see what exactly this is. I''m giving you a 10, which I''ve only done a couple times since I''ve been a member. Great job.</td>', 'I''ve no clue what I''m looking at, but I love it. This is just so awesome. The striations in the blue contrast really well with the smoothness of the yellow area. Curious to see notes after the fact to see what exactly this is. I''m giving you a 10, which I''ve only done a couple times since I''ve been a member. Great job.', '2010-12-08 01:33:10.000000', NULL, 1),
(6248271, 924276, 93565, '<td valign="top">This looks very much like a painting. I like this a good deal. Nice job. The subtle green is a nice touch.</td>', 'This looks very much like a painting. I like this a good deal. Nice job. The subtle green is a nice touch.', '2010-12-08 01:33:13.000000', NULL, 1),
