(6248277, 924097, 93565, '<td valign="top">A pleasant departure from the subject matter everybody else went with. Good job thinking of a novel approach.</td>', 'A pleasant departure from the subject matter everybody else went with. Good job thinking of a novel approach.', '2010-12-08 01:34:41.000000', NULL, 1),
(6248284, 924070, 51638, '<td valign="top">Not completely original, but pretty well done all the same.</td>', 'Not completely original, but pretty well done all the same.', '2010-12-08 01:39:41.000000', NULL, 1),
(6248296, 924289, 51638, '<td valign="top">I could be pedantic and correct your grammar, but instead I''ll just vote and move along. :)</td>', 'I could be pedantic and correct your grammar, but instead I''ll just vote and move along. :)', '2010-12-08 01:44:29.000000', NULL, 1),
(6248300, 923650, 51638, '<td valign="top">Effective shot, that would have been even better with a nice shiny clean car. :)</td>', 'Effective shot, that would have been even better with a nice shiny clean car. :)', '2010-12-08 01:45:33.000000', NULL, 1),
