(6252219, 923937, 97225, '<td valign="top">Ha, you and I were onto the same thing, but your picture conveys speed more than mine does. (I''ll bet my dog is faster though.)</td>', 'Ha, you and I were onto the same thing, but your picture conveys speed more than mine does. (I''ll bet my dog is faster though.)', '2010-12-12 23:50:23.000000', NULL, 1),
(6252437, 923848, 22689, '<td valign="top">Amazing waterdrops in motion ! I really like how they stand out from the quite uniform background.<br/>Great !</td>', 'Amazing waterdrops in motion ! I really like how they stand out from the quite uniform background.Great !', '2010-12-13 05:05:03.000000', NULL, 1),
(6252442, 923513, 22689, '<td valign="top">I like the different contrasts : the dark night and some powerful lights, the cruise ship and the small boats, the stillness and the movement and surely more important the contrasts that this photo implies.<br/>Great photo !</td>', 'I like the different contrasts : the dark night and some powerful lights, the cruise ship and the small boats, the stillness and the movement and surely more important the contrasts that this photo implies.Great photo !', '2010-12-13 05:35:54.000000', NULL, 1),
(6252453, 924236, 22689, '<td valign="top">I like the idea very much !<br/>(Maybe it''s because I often can''t go outside to take photos.)<br/> <br/>But photos taken "indoors" are not easier (lighting, creativity), so I really appreciate the effort in this one.<br/>A 8 for me.</td>', 'I like the idea very much !(Maybe it''s because I often can''t go outside to take photos.) But photos taken "indoors" are not easier (lighting, creativity), so I really appreciate the effort in this one.A 8 for me.', '2010-12-13 05:57:20.000000', NULL, 1),
(6252480, 924283, 22689, '<td valign="top">One of my fav !<br/>Great capture, we sometimes forget how lucky we are wih the companionship offered by the pets.</td>', 'One of my fav !Great capture, we sometimes forget how lucky we are wih the companionship offered by the pets.', '2010-12-13 06:49:56.000000', NULL, 1),
